// ----- actions -----
enum HgActionType : uint8_t {
  ACT_NONE = 0,
  ACT_RELAY_ON,       // target = relay index
  ACT_RELAY_OFF,
  ACT_RELAY_TOGGLE,
  ACT_MOOD,           // target = mood id, strips = LED mask
  ACT_STRIP_ON,       // strips = LED mask
  ACT_STRIP_OFF,
  ACT_ALL_RELAYS_OFF,
  ACT_COUNT
};

struct HgAction {
  uint8_t type;
  uint8_t target;
  uint8_t strips;     // bit 0 = LED 1, bit 1 = LED 2
};

// ----- commands queued from web requests / JSON API to loop() -----
enum HgCmdType : uint8_t { CMD_RELAY, CMD_MOOD, CMD_SCENE, CMD_STRIP, CMD_ALL_OFF, CMD_MIC, CMD_LEVEL, CMD_AWAY };
