// ----- hardware objects -----
struct HgRelay {
  char     name[HG_NAME_LEN];
  int8_t   pin;
  uint8_t  icon;
  bool     activeLow;   // most 5 V relay boards switch on when their input is pulled LOW
  bool     keep;        // "stays on": scenes, motion sensors and "all off" never switch it off (fridge, aquarium)
  uint8_t  powerOn;     // state after boot: 0 = off, 1 = on, 2 = last state
  uint16_t autoOffMin;  // switch off automatically after this many minutes, 0 = never
  // runtime
  bool     state;
  bool     allocated;
  uint8_t  pinError;    // 0 = ok, 1 = not a usable pin, 2 = pin used by something else
  uint32_t onSince;
  uint8_t  lastSrc;     // HgSource of the last change
  uint32_t lastChange;  // hgUptimeSec() of the last change, 0 = unchanged since boot
};

enum HgSwitchType : uint8_t { SW_DRY = 0, SW_AC = 1 };
enum HgSwitchMode : uint8_t { SW_TOGGLE = 0, SW_FOLLOW = 1 };

struct HgSwitch {
  int8_t   pin;
  uint8_t  type;        // HgSwitchType
  uint8_t  mode;        // HgSwitchMode
  int8_t   relay;       // relay controlled by this switch, -1 = none
  bool     invert;      // input is active HIGH instead of active LOW
  // runtime
  bool     allocated;
  uint8_t  pinError;
  bool     state;       // debounced state
  bool     rawPrev;
  uint32_t rawSince;
};

struct HgSensor {
  char     name[HG_NAME_LEN];
  int8_t   pin;
  bool     enabled;
  bool     nightOnly;   // only react between sunset and sunrise
  bool     undo;        // switch things back off when the hold time has passed
  uint16_t holdSec;     // seconds without motion before "undo"
  HgAction actions[HG_ACTIONS];
  // runtime
  bool     allocated;
  uint8_t  pinError;
  bool     motion;
  bool     rawPrev;
  uint32_t rawSince;
  bool     active;      // actions have run and the hold timer is running
  uint32_t lastMotion;
};

struct HgScene {
  char     name[HG_NAME_LEN];
  HgAction actions[HG_ACTIONS];
};

