enum HgSchedType : uint8_t { SCH_CLOCK = 0, SCH_SUNRISE = 1, SCH_SUNSET = 2 };

// runs its actions once per day at a clock time or relative to sunrise / sunset
struct HgSchedule {
  bool     used = false;                // slot holds a schedule (the list is variable length, see applyConfig())
  char     name[HG_NAME_LEN] = "";      // empty = never named, sent as "Schedule N"
  bool     en = false;
  uint8_t  days = 0x7F;                 // bit 0 = Monday .. bit 6 = Sunday
  uint8_t  type = SCH_CLOCK;            // HgSchedType
  int16_t  atMin = 0;                   // SCH_CLOCK: minute of day 0-1439, sunrise/sunset: offset -180..180
  HgAction actions[HG_ACTIONS] = {};
  // runtime
  uint16_t firedDay = 0;                // local day number (days since 1970) of the last run, 0 = none
};

// away mode (presence simulation): switches relays at random while a daily time window is open
struct HgAway {
  bool     en = false;
  uint8_t  rel = 0;                     // relay bitmask
  uint16_t from = 1110;                 // window start, local minute of day (18:30)
  uint16_t to = 1410;                   // window end, not included (23:30); from > to wraps past midnight
  uint16_t gapMin = 10;                 // random pause between two toggles of a relay, in minutes
  uint16_t gapMax = 45;
  int16_t  mood = -1;                   // mood applied when the window opens, -1 = none
  uint8_t  ms = 3;                      // strips for the mood: bit 0 = LED 1, bit 1 = LED 2
};

// a mood captured from a segment ("Save current look")
struct HgMood {
  bool     used;
  int8_t   replaces;    // index of the built-in mood this one overrides, -1 = additional mood
  char     name[HG_NAME_LEN];
  char     fx[HG_FXNAME_LEN];  // effect / palette are stored by name, so moods survive
  char     pal[HG_FXNAME_LEN]; // effect list changes in future WLED versions
  uint8_t  fxId, palId;        // fallback if a name cannot be found anymore
  uint8_t  sx, ix, c1, c2, c3, bri;
  bool     o1, o2, o3;           // effect option checkboxes (e.g. "Zebra" of Shimmer)
  uint32_t col[3];
};

// built-in moods; effect and palette names must match WLED's effect and palette lists
struct HgBuiltinMood {
  const char *name;
  const char *fx;
  const char *pal;      // "" = use the effect's default palette
  uint8_t     sx, ix, bri;
  uint32_t    col[3];   // segment colors
  uint32_t    preview[3]; // gradient shown on the web page
  bool        sound;    // needs the microphone
};

